DROP TABLE IF EXISTS `fixed_assets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fixed_assets` (
  `id` varchar(64) NOT NULL COMMENT '主键',
  `code` varchar(255) DEFAULT NULL COMMENT '必填 唯一',
  `name` varchar(255) DEFAULT NULL COMMENT '必填',
  `category` varchar(64) DEFAULT NULL COMMENT 'ASSET_CATEGORY 必填',
  `brand` varchar(255) DEFAULT NULL,
  `model` varchar(255) DEFAULT NULL,
  `company_id` varchar(255) DEFAULT NULL COMMENT '→org-companies',
  `dept_id` varchar(255) DEFAULT NULL COMMENT '→org-departments',
  `user_id` varchar(255) DEFAULT NULL COMMENT '→org-users',
  `location` varchar(255) DEFAULT NULL,
  `purchase_date` datetime(3) DEFAULT NULL,
  `inbound_date` datetime(3) DEFAULT NULL,
  `amount` decimal(20,6) DEFAULT NULL,
  `original` decimal(20,6) DEFAULT NULL,
  `net` decimal(20,6) DEFAULT NULL,
  `status` varchar(64) DEFAULT NULL COMMENT 'ASSET_STATUS 必填',
  `depreciate` tinyint(1) DEFAULT NULL,
  `purchase_mode` varchar(64) DEFAULT NULL COMMENT 'PURCHASE_MODE',
  `lease_months` bigint DEFAULT NULL,
  `source_tag` varchar(64) DEFAULT NULL COMMENT '数据来源标注，如「期初导入」',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `version` int DEFAULT '1' COMMENT '乐观锁版本',
  PRIMARY KEY (`id`),
  KEY `idx_fa_company` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='固定资产台账';
